import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Extract configuration
  const scenePosition = config.scenePosition || {
    x: 0,
    y: 3,
    z: 0,
    rotationXYZ: [0, 0, 0],
    scaleXYZ: [1, 1, 1],
  };
  const imageUrl = config.assets?.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const atlasRegion = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };

  // Load texture using cached context loader
  const texture = ctx.textureLoader.load(imageUrl);
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearMipMapLinearFilter;

  // Create plane geometry with aspect ratio matching the atlas region
  const aspectRatio = atlasRegion.width / atlasRegion.height;
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1.0);

  // Calculate UV coordinates for the atlas region
  // Assume atlas is 2048x2048 (standard size)
  const ATLAS_SIZE = 2048;
  const minU = atlasRegion.x / ATLAS_SIZE;
  const minV = atlasRegion.y / ATLAS_SIZE;
  const maxU = (atlasRegion.x + atlasRegion.width) / ATLAS_SIZE;
  const maxV = (atlasRegion.y + atlasRegion.height) / ATLAS_SIZE;

  // Remap the plane's default UVs [0,1] to the atlas region
  const uvAttribute = geometry.getAttribute('uv');
  const uvArray = uvAttribute.array;

  for (let i = 0; i < uvArray.length; i += 2) {
    const u = uvArray[i];
    const v = uvArray[i + 1];
    uvArray[i] = minU + u * (maxU - minU);
    uvArray[i + 1] = minV + v * (maxV - minV);
  }
  uvAttribute.needsUpdate = true;

  // Create material with the texture
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and configure mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(scenePosition.x, scenePosition.y, scenePosition.z);
  mesh.rotation.set(
    scenePosition.rotationXYZ[0],
    scenePosition.rotationXYZ[1],
    scenePosition.rotationXYZ[2]
  );
  mesh.scale.set(
    scenePosition.scaleXYZ[0],
    scenePosition.scaleXYZ[1],
    scenePosition.scaleXYZ[2]
  );

  group.add(mesh);

  // Setup cleanup function to dispose all resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Setup empty event handlers object
  group.userData.handlers = {};

  return group;
}
